"""Embedding provider contract and deterministic test embedding."""

import hashlib
import math
import re
import threading
import time
from collections.abc import Sequence
from typing import Protocol

import httpx


class EmbeddingProvider(Protocol):
    dimension: int

    def embed(
        self, text: str, *, task_type: str = "RETRIEVAL_QUERY"
    ) -> Sequence[float]:
        """Return an embedding generated by a configured, trusted model."""


class HashEmbeddingProvider:
    """Deterministic local embedding for tests and development only.

    This is not a semantic model and must not be presented as production retrieval quality.
    """

    def __init__(self, dimension: int = 64) -> None:
        self.dimension = dimension

    def embed(self, text: str, *, task_type: str = "RETRIEVAL_QUERY") -> tuple[float, ...]:
        values = [0.0] * self.dimension
        for token in text.lower().split():
            index = int(hashlib.sha256(token.encode()).hexdigest(), 16) % self.dimension
            values[index] += 1.0
        norm = math.sqrt(sum(value * value for value in values)) or 1.0
        return tuple(value / norm for value in values)


class GeminiEmbeddingProvider:
    """Gemini retrieval embeddings with dimensions compatible with pgvector."""

    _endpoint = "https://generativelanguage.googleapis.com/v1beta/models/{model}:embedContent"
    _batch_endpoint = (
        "https://generativelanguage.googleapis.com/v1beta/models/{model}:batchEmbedContents"
    )
    _batch_size = 16
    _task_types = {"RETRIEVAL_QUERY", "RETRIEVAL_DOCUMENT"}
    _cooldown_lock = threading.Lock()
    _cooldowns: dict[bytes, float] = {}

    def __init__(
        self,
        api_key: str,
        model: str = "gemini-embedding-001",
        dimension: int = 1536,
        client: httpx.Client | None = None,
    ) -> None:
        if not api_key:
            raise ValueError("GEMINI_API_KEY is required for semantic agricultural retrieval")
        if dimension <= 0:
            raise ValueError("embedding dimension must be positive")
        self.api_key = api_key
        self.model = model
        self.dimension = dimension
        self.client = client or httpx.Client(timeout=20)

    def embed(
        self, text: str, *, task_type: str = "RETRIEVAL_QUERY"
    ) -> tuple[float, ...]:
        if not text.strip():
            raise ValueError("embedding text must not be empty")
        if task_type not in self._task_types:
            raise ValueError("task_type must be RETRIEVAL_QUERY or RETRIEVAL_DOCUMENT")
        cooldown_key = hashlib.sha256(f"{self.api_key}:{self.model}".encode()).digest()
        with self._cooldown_lock:
            retry_after = self._cooldowns.get(cooldown_key, 0) - time.monotonic()
        if retry_after > 0:
            raise RuntimeError(
                "Gemini embedding quota cooldown is active; retry in "
                f"{math.ceil(retry_after)} seconds"
            )
        try:
            response = self.client.post(
                self._endpoint.format(model=self.model),
                headers={"x-goog-api-key": self.api_key},
                json={
                    "model": f"models/{self.model}",
                    "content": {"parts": [{"text": text}]},
                    "taskType": task_type,
                    "outputDimensionality": self.dimension,
                },
            )
            response.raise_for_status()
            payload = response.json()
            values = payload["embedding"]["values"]
            embedding = tuple(float(value) for value in values)
        except httpx.HTTPError as error:
            if isinstance(error, httpx.HTTPStatusError) and error.response.status_code == 429:
                retry_after = self._retry_delay(error.response)
                with self._cooldown_lock:
                    self._cooldowns[cooldown_key] = time.monotonic() + retry_after
                raise RuntimeError(
                    f"Gemini embedding quota exceeded; retry in approximately "
                    f"{math.ceil(retry_after)} seconds"
                ) from error
            raise RuntimeError("Gemini embedding request failed") from error
        except (KeyError, TypeError, ValueError) as error:
            raise RuntimeError("Gemini returned an invalid embedding response") from error
        if len(embedding) != self.dimension or not all(math.isfinite(value) for value in embedding):
            raise RuntimeError(
                f"Gemini embedding must contain {self.dimension} finite values"
            )
        return embedding

    def embed_many(
        self, texts: Sequence[str], *, task_type: str = "RETRIEVAL_DOCUMENT"
    ) -> list[tuple[float, ...]]:
        if not texts:
            return []
        if any(not text.strip() for text in texts):
            raise ValueError("embedding text must not be empty")
        if task_type not in self._task_types:
            raise ValueError("task_type must be RETRIEVAL_QUERY or RETRIEVAL_DOCUMENT")
        cooldown_key = hashlib.sha256(f"{self.api_key}:{self.model}".encode()).digest()
        self._raise_if_cooling_down(cooldown_key)
        embeddings: list[tuple[float, ...]] = []
        for start in range(0, len(texts), self._batch_size):
            batch = texts[start : start + self._batch_size]
            payload = {
                "requests": [
                    {
                        "model": f"models/{self.model}",
                        "content": {"parts": [{"text": text}]},
                        "taskType": task_type,
                        "outputDimensionality": self.dimension,
                    }
                    for text in batch
                ]
            }
            try:
                response = self.client.post(
                    self._batch_endpoint.format(model=self.model),
                    headers={"x-goog-api-key": self.api_key},
                    json=payload,
                )
                response.raise_for_status()
                values = response.json()["embeddings"]
                batch_embeddings = [
                    tuple(float(value) for value in item["values"]) for item in values
                ]
            except httpx.HTTPError as error:
                self._handle_http_error(error, cooldown_key)
            except (KeyError, TypeError, ValueError) as error:
                raise RuntimeError("Gemini returned an invalid batch embedding response") from error
            if len(batch_embeddings) != len(batch):
                raise RuntimeError(
                    "Gemini returned a different number of embeddings than requested"
                )
            if any(
                len(embedding) != self.dimension
                or not all(math.isfinite(value) for value in embedding)
                for embedding in batch_embeddings
            ):
                raise RuntimeError(
                    f"Gemini batch embeddings must each contain {self.dimension} finite values"
                )
            embeddings.extend(batch_embeddings)
        return embeddings

    @classmethod
    def _raise_if_cooling_down(cls, cooldown_key: bytes) -> None:
        with cls._cooldown_lock:
            retry_after = cls._cooldowns.get(cooldown_key, 0) - time.monotonic()
        if retry_after > 0:
            raise RuntimeError(
                "Gemini embedding quota cooldown is active; retry in "
                f"{math.ceil(retry_after)} seconds"
            )

    @classmethod
    def _handle_http_error(cls, error: httpx.HTTPError, cooldown_key: bytes) -> None:
        if isinstance(error, httpx.HTTPStatusError) and error.response.status_code == 429:
            retry_after = cls._retry_delay(error.response)
            with cls._cooldown_lock:
                cls._cooldowns[cooldown_key] = time.monotonic() + retry_after
            raise RuntimeError(
                f"Gemini embedding quota exceeded; retry in approximately "
                f"{math.ceil(retry_after)} seconds"
            ) from error
        raise RuntimeError("Gemini embedding request failed") from error

    @staticmethod
    def _retry_delay(response: httpx.Response) -> float:
        try:
            details = response.json().get("error", {}).get("details", [])
        except (ValueError, AttributeError):
            details = []
        for detail in details:
            retry_delay = detail.get("retryDelay") if isinstance(detail, dict) else None
            if isinstance(retry_delay, str):
                match = re.fullmatch(r"(\d+(?:\.\d+)?)s", retry_delay)
                if match:
                    return float(match.group(1))
        return 60.0


def cosine_similarity(left: Sequence[float], right: Sequence[float]) -> float:
    if len(left) != len(right):
        raise ValueError("embedding dimensions must match")
    return sum(a * b for a, b in zip(left, right, strict=True))
